  /**
   * Prepare melt token data, sign the inputs and returns an object ready to be mined
   *
   * @memberof HathorWalletServiceWallet
   * @inner
   */
  async prepareMeltTokensData(token, amount, options = {}) {
    this.failIfWalletNotReady();
    const newOptions = {
      address: null,
      changeAddress: null,
      createAnotherMelt: true,
      meltAuthorityAddress: null,
      allowExternalMeltAuthorityAddress: false,
      pinCode: null,
      signTx: true,
      ...options
    };
    if (newOptions.meltAuthorityAddress && !newOptions.allowExternalMeltAuthorityAddress) {
      // Validate that the melt authority address belongs to the wallet
      const checkAddressMineMap = await this.checkAddressesMine([newOptions.meltAuthorityAddress]);
      if (!checkAddressMineMap[newOptions.meltAuthorityAddress]) {
        throw new _errors.SendTxError('The melt authority address must belong to your wallet.');
      }
    }

    // Get token info
    const {
      tokenInfo
    } = await this.getTokenDetails(token);
    if (!tokenInfo) {
      throw new _errors.TokenNotFoundError(token);
    }

    // 1. Calculate HTR withdraw
    let withdraw = 0n;
    if (tokenInfo?.version === _types3.TokenVersion.DEPOSIT) {
      withdraw = this.getWithdrawAmount(amount);
    }

    // 2. Get utxos for custom token to melt
    const {
      utxos: tokenUtxos,
      changeAmount
    } = await this.getUtxosForAmount(amount, {
      token
    });
    if (tokenUtxos.length === 0) {
      throw new _errors.UtxoError(`Not enough tokens to be melted. Token: ${token} - Amount: ${amount}.`);
    }

    // 3. Get melt authority
    const meltAuthorities = await this.getMeltAuthority(token, {
      many: false,
      skipSpent: true
    });
    if (meltAuthorities.length === 0) {
      throw new _errors.UtxoError(`No authority utxo available for melting tokens. Token: ${token}.`);
    }
    // it's safe to assume that we have an utxo in the array
    const meltUtxo = meltAuthorities[0];

    // 4. Create inputs from utxos and track address paths for signing
    const inputsObj = [];
    const addressPaths = [];

    // Add token inputs
    for (const utxo of tokenUtxos) {
      inputsObj.push(_helpers.default.parseToInput(utxo));
      addressPaths.push(utxo.addressPath);
    }

    // Add melt authority input and resolve its address path
    inputsObj.push(_helpers.default.parseToInput(meltUtxo));
    addressPaths.push(await this.getAuthorityAddressPath(meltUtxo.address));

    // Create outputs
    const outputsObj = [];

    // a. withdrawal
    // We may have nothing to withdraw
    if (withdraw) {
      outputsObj.push(this.createOutput(withdraw, newOptions.address, 0)); // token data is 0 because we are withdrawing HTR
    }
    if (newOptions.createAnotherMelt) {
      // b. Melt authority
      const authorityAddressObj = this.validateAddress(newOptions.meltAuthorityAddress);
      const p2pkhAuthorityScript = authorityAddressObj.getScript();
      outputsObj.push(new _output.default(_constants.TOKEN_MELT_MASK, p2pkhAuthorityScript, {
        tokenData: _constants.AUTHORITY_TOKEN_DATA
      }));
    }
    if (changeAmount) {
      // c. Token change output
      outputsObj.push(this.createOutput(changeAmount, newOptions.changeAddress, 1));
    }
    const headers = [];
    if (tokenInfo?.version === _types3.TokenVersion.FEE) {
      const mappedOutputs = outputsObj.map(output => this.mapToDataOutput(output, token));
      const tokenData = {
        uid: tokenInfo.id,
        name: tokenInfo.name,
        symbol: tokenInfo.symbol,
        version: tokenInfo.version
      };
      const fee = await _fee2.Fee.calculate(tokenUtxos,
      // we are using the token utxos instead of the inputs we need to check if this utxo is an authority utxo
      mappedOutputs, new Map([[tokenData.uid, tokenData]]));
      if (fee > 0) {
        headers.push(new _fee.default([{
          tokenIndex: 0,
          amount: fee
        }]));
      }

      // Get utxos for HTR
      const {
        utxos: htrUtxos,
        changeAmount: htrChangeAmount
      } = await this.getUtxosForAmount(fee, {
        token: _constants.NATIVE_TOKEN_UID
      });
      if (htrUtxos.length === 0) {
        throw new _errors.UtxoError(`No utxos available to fill the request. Token: HTR - Amount: ${fee}.`);
      }

      // Add HTR inputs
      for (const utxo of htrUtxos) {
        inputsObj.push(_helpers.default.parseToInput(utxo));
        addressPaths.push(utxo.addressPath);
      }

      // Htr isn't billable, so we can append it here after calculating the fee
      if (htrChangeAmount) {
        // HTR change output
        outputsObj.push(this.createOutput(htrChangeAmount, newOptions.changeAddress));
      }
    }
    const tx = new _transaction2.default(inputsObj, outputsObj, {
      headers
    });
    tx.tokens = [token];

    // Sign transaction
    if (newOptions.signTx) {
      if (this.storage.hasTxSignatureMethod()) {
        await this.signInputsExternally(tx, newOptions.pinCode);
      } else {
        if (!newOptions.pinCode) {
          throw new Error('PIN not specified in prepareMeltTokensData options');
        }
        await this.signInputsByPath(tx, newOptions.pinCode, addressPaths);
      }
    }
    tx.prepareToSend(_transaction.default.getWeightConstantsFromStorage(this.storage));
    return tx;
  }
  mapToDataOutput(output, token) {
    let authorities = 0n;
    if (output.isAuthority()) {
      if (output.isMint()) {
        authorities = 1n;
      }
      if (output.isMelt()) {
        authorities = 2n;
      }
    }
    return {
      token,
      value: output.value,
      authorities,
      data: '',
      type: output.getType(this.network)
    };
  }

